import { useState } from 'react';
import { registerUser } from './utils/api';

function RegisterForm() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const [name, setName] = useState(''); // for institution/company
  const [personalInfo, setPersonalInfo] = useState({}); // for student
  const [education, setEducation] = useState({}); // for student
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleRegister = async (e) => {
    e.preventDefault();

    let userData = {};
    if (role === 'student') {
      userData = { personalInfo, education };
    } else {
      userData = { name };
    }

    try {
      const result = await registerUser({ email, password, role, userData });
      setSuccess('Registered successfully! Token: ' + result.token);
      setError('');
    } catch (err) {
      setError(err.message);
      setSuccess('');
    }
  };

  return (
    <form onSubmit={handleRegister}>
      <input type="email" placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} required />
      <input type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)} required />
      <select value={role} onChange={e => setRole(e.target.value)}>
        <option value="student">Student</option>
        <option value="institution">Institution</option>
        <option value="company">Company</option>
      </select>
      {role === 'student' && (
        <>
          {/* Add inputs for personalInfo and education */}
        </>
      )}
      {role !== 'student' && (
        <input type="text" placeholder="Name" value={name} onChange={e => setName(e.target.value)} required />
      )}
      <button type="submit">Register</button>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {success && <p style={{ color: 'green' }}>{success}</p>}
    </form>
  );
}

export default RegisterForm;
